#!/usr/bin/python3 -I
"""Génère /devhoros/php127/ext/normalizer_table_gen.go depuis unicodedata (python3).

Usage : gen_normalizer_table.py SORTIE.go
Chaque ligne de normDecomp est « CP;K;D1 D2 ... » (hexadécimal) : K vaut C pour une décomposition canonique,
K pour une décomposition de compatibilité ; les syllabes hangûl sont algorithmiques et absentes.
normCCC liste « CP;CLASSE » pour toute classe combinatoire non nulle ; normExcl liste les décompositions
canoniques à deux points de code exclues de la composition (NFC(cp) != cp).
"""
import sys
import unicodedata

decomp, ccc, excl = [], [], []
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF or 0xAC00 <= cp <= 0xD7A3:
        continue
    ch = chr(cp)
    c = unicodedata.combining(ch)
    if c:
        ccc.append("%X;%d" % (cp, c))
    d = unicodedata.decomposition(ch)
    if not d:
        continue
    parts = d.split()
    kind = "C"
    if parts[0].startswith("<"):
        kind = "K"
        parts = parts[1:]
    decomp.append("%X;%s;%s" % (cp, kind, " ".join(parts)))
    if kind == "C" and len(parts) == 2 and unicodedata.normalize("NFC", ch) != ch:
        excl.append("%X" % cp)

out = [
    "// Code generated by ext/testdata/gen_normalizer_table.py from python3 unicodedata %s; DO NOT EDIT." % unicodedata.unidata_version,
    "",
    "package ext",
    "",
    "const normUnicodeVersion = \"%s\"" % unicodedata.unidata_version,
    "",
    "const normDecomp = `" + "\n".join(decomp) + "`",
    "",
    "const normCCC = `" + "\n".join(ccc) + "`",
    "",
    "const normExcl = `" + "\n".join(excl) + "`",
    "",
]
with open(sys.argv[1], "w", encoding="ascii") as f:
    f.write("\n".join(out))
